CRYPTO_MODULE_VERSIONS = {'cryptography': '50.0.1', 'cffi': '2.0.0', 'pycparser': '3.00', '_cffi_backend': '2.0.0'}
CRYPTO_PLATFORM = {'python': '3.11.13', 'implementation': 'CPython', 'system': 'Linux', 'machine': 'x86_64'}
